#ifndef RBTREE_H
#define RBTREE_H
#include <stddef.h>
typedef struct rbtree rbtree_t;
typedef void (*rb_value_free_fn)(void *value);
/* Returns NULL on allocation failure.
* value_free may be NULL (values not owned). */
rbtree_t *rb_create(rb_value_free_fn value_free);
/* Mutation 2: node storage drawn from an internal slab pool. */
rbtree_t *rb_create_pooled(rb_value_free_fn value_free);
/* Copies key (tree owns the copy).
* Takes ownership of value ONLY on success.
* Overwriting an existing key frees the old value via value_free.
* Returns 0 on success, -1 on allocation failure (tree unchanged, value NOT
* consumed; caller still owns it). */
int rb_insert(rbtree_t *t, const char *key, void *value);
/* Returns the value, or NULL if absent. Tree retains ownership. */
void *rb_find(const rbtree_t *t, const char *key);
/* Removes key; frees the key copy and the value.
* Returns 0, or -1 if absent. */
int rb_delete(rbtree_t *t, const char *key);
size_t rb_size(const rbtree_t *t);
/* In-order. Mutation 3: O(1) auxiliary space, no recursion. */
void rb_foreach(const rbtree_t *t,
void (*fn)(const char *key, void *value, void *ctx),
void *ctx);
/* Returns 0 iff all red-black invariants hold
* (see the baseline section). */
int rb_validate(const rbtree_t *t);
/* Frees all nodes, key copies, and (if owned) values.
* Mutation 3: O(1) auxiliary space, no recursion. NULL-safe. */
void rb_destroy(rbtree_t *t);
/* Mutation 4 (The Reach): O(1) copy-on-write snapshot.
* NULL on alloc failure. */
rbtree_t *rb_snapshot(rbtree_t *t);
#endif#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "rbtree.h"
#include "fault_alloc.h"
#include "pool.h"

typedef enum { RED, BLACK } rb_color_t;

typedef struct rb_node {
    char *key; // Pointer to a copy of string key
    void *value; // Pointer storing node's value
    rb_color_t color; // Node's color
    struct rb_node *parent; // Pointer towards parent node (Above)
    struct rb_node *left; // Pointer towards the smaller child node
    struct rb_node *right; // Pointer towards the larger child node
} rb_node_t;

/* The concrete definition of the opaque `rbtree_t` from rbtree.h. Callers only
 * ever hold a `struct rbtree *`, so every field here is private and may change
 * without touching the graded contract in include/rbtree.h. One of these is
 * allocated per tree by rb_create() and released by rb_destroy(). */
struct rbtree {
    /* Current root of the tree. Points at `nil` (never a raw NULL) when the tree
     * is empty, so traversal and fixup code can treat an empty tree and a real
     * subtree uniformly. Updated by insert/delete and by the rotation helpers. */
    rb_node_t *root;

    /* The single shared sentinel standing in for every NULL child and for the
     * parent of the root. Allocated once in rb_create(); its `color` is always
     * BLACK, and its key/value/child pointers are unused. Using one sentinel
     * (rather than NULL) removes the null checks from the red-black fixup and
     * lets delete-fixup temporarily write `nil->parent`. Must be freed exactly
     * once, by rb_destroy(), after all real nodes are gone. */
    rb_node_t *nil;

    /* Caller-supplied destructor for owned values, captured from rb_create().
     * May be NULL, meaning the tree does not own the values and must not free
     * them. When non-NULL it is invoked on the old value when a key is
     * overwritten by rb_insert(), on the removed value by rb_delete(), and on
     * every remaining value by rb_destroy(). */
    rb_value_free_fn value_free;

    /* Number of key/value pairs currently stored (excludes the `nil` sentinel).
     * Maintained incrementally: +1 on a successful insert of a new key, +0 when
     * an insert overwrites an existing key, -1 on a successful delete. Returned
     * as-is by rb_size(), which is therefore O(1). */
    size_t size;

    /* Slab pool that real nodes are drawn from, or NULL for an rb_create()
     * tree, whose nodes come straight from rb_malloc. The nil sentinel is
     * always rb_malloc'd. Released by rb_destroy() after all nodes. */
    rb_pool_t *pool;
};

/* Node storage: from the pool when the tree has one, else rb_malloc. */
static rb_node_t *node_alloc(rbtree_t *t) {
    return (t->pool != NULL) ? pool_alloc(t->pool) : rb_malloc(sizeof(rb_node_t));
}

static void node_free(rbtree_t *t, rb_node_t *n) {
    if (t->pool != NULL) {
        pool_free(t->pool, n);
    } else {
        rb_free(n);
    }
}

/* Allocates an empty tree and its `nil` sentinel.
 * `value_free` is stored verbatim; NULL means the tree does not own values.
 * Returns NULL on allocation failure, having freed any partial allocation. */
rbtree_t *rb_create(rb_value_free_fn value_free) {
    rbtree_t *t = rb_malloc(sizeof *t);
    if (t == NULL) {
        return NULL;
    }

    rb_node_t *nil = rb_malloc(sizeof *nil);
    if (nil == NULL) {
        goto fail_tree;
    }
    /* The sentinel is always black; its links point at itself so that a stray
     * traversal off a leaf terminates instead of dereferencing NULL. */
    nil->key = NULL;
    nil->value = NULL;
    nil->color = BLACK;
    nil->parent = nil;
    nil->left = nil;
    nil->right = nil;

    t->nil = nil;
    t->root = nil; /* empty tree: root == nil, never NULL */
    t->value_free = value_free;
    t->size = 0;
    t->pool = NULL;
    return t;

fail_tree:
    rb_free(t);
    return NULL;
}

/* As rb_create, but nodes come from a slab pool owned by the tree.
 * Returns NULL on allocation failure, having freed any partial allocation. */
rbtree_t *rb_create_pooled(rb_value_free_fn value_free) {
    rbtree_t *t = rb_create(value_free);
    if (t == NULL) {
        return NULL;
    }
    t->pool = pool_create(sizeof(rb_node_t));
    if (t->pool == NULL) {
        goto fail_tree;
    }
    return t;

fail_tree:
    rb_destroy(t); /* empty tree: frees just the sentinel and the struct */
    return NULL;
}

/* Post-order free of one subtree. Depth is O(log n) for a valid RB tree. */
static void rb_free_subtree(rbtree_t *t, rb_node_t *n) {
    if (n == t->nil) {
        return;
    }
    rb_free_subtree(t, n->left);
    rb_free_subtree(t, n->right);
    rb_free(n->key);
    if (t->value_free != NULL) {
        t->value_free(n->value);
    }
    node_free(t, n);
}

/* Frees every node, key copy, and (if owned) value, then the tree and its
 * sentinel. NULL-safe per the contract. */
void rb_destroy(rbtree_t *t) {
    if (t == NULL) {
        return;
    }
    rb_free_subtree(t, t->root);
    pool_destroy(t->pool); /* NULL-safe; nodes already returned to it */
    rb_free(t->nil);
    rb_free(t);
}

/* Number of key/value pairs stored. NULL-safe, matching rb_destroy's spirit. */
size_t rb_size(const rbtree_t *t) {
    return (t == NULL) ? 0 : t->size;
}

/* Recursively checks the subtree rooted at n. Returns that subtree's
 * black-height (black nodes on any n-to-nil path, counting the terminal nil),
 * or -1 if any red-black or BST invariant is violated within it.
 * invariant: on return *prev is the greatest key visited so far by the global
 * in-order walk (NULL before the first key), and *count has been incremented
 * once per real (non-nil) node visited so far.
 * Assumes an acyclic tree; a corrupted cycle would recurse unboundedly (out of
 * scope for this milestone). */
static int rb_check(const rbtree_t *t, const rb_node_t *n,
                    const char **prev, size_t *count) {
    if (n == t->nil) {
        return 1; /* terminal nil counts as one black node */
    }

    /* property 2: a red node must not have a red child (nil reads BLACK) */
    if (n->color == RED &&
        (n->left->color == RED || n->right->color == RED)) {
        return -1;
    }

    int lh = rb_check(t, n->left, prev, count);
    if (lh < 0) {
        return -1;
    }

    /* property 4: in-order keys strictly increasing (checked at the in-order
     * position, between the left and right recursion) */
    if (*prev != NULL && strcmp(*prev, n->key) >= 0) {
        return -1;
    }
    *prev = n->key;
    *count += 1; /* property 5: count this real node */

    int rh = rb_check(t, n->right, prev, count);
    if (rh < 0) {
        return -1;
    }

    /* property 3: both sides have equal black-height */
    if (lh != rh) {
        return -1;
    }

    return lh + (n->color == BLACK ? 1 : 0);
}

/* Returns 0 iff all red-black invariants hold, -1 otherwise. */
int rb_validate(const rbtree_t *t) {
    if (t == NULL) {
        return -1; /* a NULL tree is not a valid RB tree */
    }

    /* property 1: root is black. Empty tree: root == nil, which is BLACK, so
     * the empty tree is accepted here too. */
    if (t->root->color != BLACK) {
        return -1;
    }

    const char *prev = NULL; /* greatest key seen by the in-order walk */
    size_t count = 0;        /* real nodes seen by the walk */
    if (rb_check(t, t->root, &prev, &count) < 0) {
        return -1;
    }

    /* property 5: cached size matches the real node count */
    if (count != t->size) {
        return -1;
    }

    return 0;
}

/* Heap copy of a NUL-terminated key; the tree owns the result. NULL on OOM.
 * Not strdup(): under -std=c23 (strict) the glibc headers may not declare it,
 * and an implicit declaration would trip -Werror. */
static char *dup_key(const char *key) {
    size_t n = strlen(key) + 1;
    char *copy = rb_malloc(n);
    if (copy == NULL) {
        return NULL;
    }
    memcpy(copy, key, n);
    return copy;
}

/* CLRS left rotation, sentinel form. Assumes x->right != t->nil. Retargets
 * t->root when x was the root. */
static void left_rotate(rbtree_t *t, rb_node_t *x) {
    rb_node_t *y = x->right; /* y takes x's slot; x becomes y->left */
    x->right = y->left;
    if (y->left != t->nil) {
        y->left->parent = x;
    }
    y->parent = x->parent;
    if (x->parent == t->nil) {
        t->root = y;
    } else if (x == x->parent->left) {
        x->parent->left = y;
    } else {
        x->parent->right = y;
    }
    y->left = x;
    x->parent = y;
}

/* Mirror of left_rotate. Assumes x->left != t->nil. */
static void right_rotate(rbtree_t *t, rb_node_t *x) {
    rb_node_t *y = x->left; /* y takes x's slot; x becomes y->right */
    x->left = y->right;
    if (y->right != t->nil) {
        y->right->parent = x;
    }
    y->parent = x->parent;
    if (x->parent == t->nil) {
        t->root = y;
    } else if (x == x->parent->right) {
        x->parent->right = y;
    } else {
        x->parent->left = y;
    }
    y->right = x;
    x->parent = y;
}

/* CLRS RB-INSERT-FIXUP. z is the freshly linked RED node; restore the red-black
 * invariants by recoloring and rotating up the tree. */
static void rb_insert_fixup(rbtree_t *t, rb_node_t *z) {
    /* invariant: z is RED; the only invariant that can be broken is a red z
     * with a red parent. When z is the root, z->parent is t->nil (BLACK) and
     * the loop exits immediately. */
    while (z->parent->color == RED) {
        if (z->parent == z->parent->parent->left) {
            rb_node_t *uncle = z->parent->parent->right;
            if (uncle->color == RED) {
                /* case 1: red uncle -> recolor and move up */
                z->parent->color = BLACK;
                uncle->color = BLACK;
                z->parent->parent->color = RED;
                z = z->parent->parent;
            } else {
                if (z == z->parent->right) {
                    /* case 2: triangle -> rotate to a line */
                    z = z->parent;
                    left_rotate(t, z);
                }
                /* case 3: line -> recolor and rotate the grandparent */
                z->parent->color = BLACK;
                z->parent->parent->color = RED;
                right_rotate(t, z->parent->parent);
            }
        } else {
            /* mirror image: parent is a right child */
            rb_node_t *uncle = z->parent->parent->left;
            if (uncle->color == RED) {
                z->parent->color = BLACK;
                uncle->color = BLACK;
                z->parent->parent->color = RED;
                z = z->parent->parent;
            } else {
                if (z == z->parent->left) {
                    z = z->parent;
                    right_rotate(t, z);
                }
                z->parent->color = BLACK;
                z->parent->parent->color = RED;
                left_rotate(t, z->parent->parent);
            }
        }
    }
    t->root->color = BLACK;
}

/* Inserts or overwrites key. On success (return 0) the tree owns value; on any
 * failure (return -1) the tree is unchanged and value is NOT consumed. */
int rb_insert(rbtree_t *t, const char *key, void *value) {
    if (t == NULL || key == NULL) {
        return -1; /* invalid args: tree unchanged, value NOT consumed */
    }

    /* phase 1: read-only BST descent, remembering the parent and last compare.
     * invariant: key, if present, is in the subtree rooted at cur; parent is
     * cur's parent. */
    rb_node_t *parent = t->nil;
    rb_node_t *cur = t->root;
    int cmp = 0;
    while (cur != t->nil) {
        cmp = strcmp(key, cur->key);
        if (cmp == 0) {
            /* overwrite existing key: no structural change, no size change.
             * The cur->value != NULL guard avoids handing a NULL to a possibly
             * non-NULL-safe value_free. */
            if (t->value_free != NULL && cur->value != NULL) {
                t->value_free(cur->value);
            }
            cur->value = value; /* ownership taken on this success path */
            return 0;
        }
        parent = cur;
        cur = (cmp < 0) ? cur->left : cur->right;
    }

    /* phase 2: allocate everything before mutating the tree. Key first: a
     * pooled node_alloc may grab a whole slab, so it must be the last thing
     * that can fail, or a failure after it would leave that slab behind. */
    char *kcopy = dup_key(key);
    if (kcopy == NULL) {
        goto fail;
    }
    rb_node_t *n = node_alloc(t);
    if (n == NULL) {
        goto fail_key;
    }
    n->key = kcopy;
    n->value = value;
    n->color = RED;
    n->left = t->nil;
    n->right = t->nil;
    n->parent = parent;

    /* phase 3: link the node (no allocation past this point) */
    if (parent == t->nil) {
        t->root = n; /* first node in the tree */
    } else if (cmp < 0) { /* cmp == strcmp(key, parent->key); loop ran >= 1 */
        parent->left = n;
    } else {
        parent->right = n;
    }
    t->size++;

    /* phase 4: restore the red-black invariants */
    rb_insert_fixup(t, n);
    return 0;

fail_key:
    rb_free(kcopy);
fail:
    return -1; /* tree untouched, value not consumed */
}

/* Returns the value stored under key, or NULL if absent. Tree retains ownership. */
void *rb_find(const rbtree_t *t, const char *key) {
    if (t == NULL || key == NULL) {
        return NULL;
    }
    const rb_node_t *x = t->root;
    /* invariant: key, if present, lies in the subtree rooted at x */
    while (x != t->nil) {
        int c = strcmp(key, x->key);
        if (c == 0) {
            return x->value;
        }
        x = (c < 0) ? x->left : x->right;
    }
    return NULL;
}

/* In-order visit of the subtree rooted at n: left, then n itself, then right.
 * invariant: every real node in the subtree is visited exactly once, in
 * strictly increasing key order. */
static void rb_foreach_subtree(const rbtree_t *t, const rb_node_t *n,
                                void (*fn)(const char *key, void *value, void *ctx),
                                void *ctx) {
    if (n == t->nil) {
        return;
    }
    rb_foreach_subtree(t, n->left, fn, ctx);
    fn(n->key, n->value, ctx);
    rb_foreach_subtree(t, n->right, fn, ctx);
}

/* In-order traversal; visits nothing on a NULL tree or NULL callback. */
void rb_foreach(const rbtree_t *t,
                void (*fn)(const char *key, void *value, void *ctx),
                void *ctx) {
    if (t == NULL || fn == NULL) {
        return;
    }
    rb_foreach_subtree(t, t->root, fn, ctx);
}

/* CLRS RB-TRANSPLANT. Replaces the subtree rooted at u with the subtree
 * rooted at v, from u->parent's perspective; does not touch u's or v's own
 * children/color. The final assignment runs even when v == t->nil, which is
 * exactly the "delete-fixup temporarily writes nil->parent" mechanism the
 * struct comment on `nil` anticipates: it gives x (in rb_delete_fixup) a
 * well-defined parent even when x is the sentinel. */
static void rb_transplant(rbtree_t *t, rb_node_t *u, rb_node_t *v) {
    if (u->parent == t->nil) {
        t->root = v;
    } else if (u == u->parent->left) {
        u->parent->left = v;
    } else {
        u->parent->right = v;
    }
    v->parent = u->parent;
}

/* CLRS TREE-MINIMUM. Assumes n != t->nil. Returns the leftmost (smallest-key)
 * node in the subtree rooted at n. */
static rb_node_t *rb_minimum(rbtree_t *t, rb_node_t *n) {
    /* invariant: n is never nil; each step strictly descends left */
    while (n->left != t->nil) {
        n = n->left;
    }
    return n;
}

/* CLRS RB-DELETE-FIXUP. x is the node that moved into a spliced-out node's
 * position (possibly t->nil) and carries one extra unit of black-ness;
 * restore the red-black invariants by recoloring and rotating up the tree.
 * Precondition: x->parent is already correct, even when x == t->nil (see
 * rb_transplant and the y->parent == z case in rb_delete). */
static void rb_delete_fixup(rbtree_t *t, rb_node_t *x) {
    /* invariant: x is doubly-black (or red-and-black); the loop climbs until
     * x reaches the root or picks up enough redness to absorb locally. */
    while (x != t->root && x->color == BLACK) {
        if (x == x->parent->left) {
            rb_node_t *sibling = x->parent->right;
            if (sibling->color == RED) {
                /* case 1: red sibling -> rotate to get a black sibling */
                sibling->color = BLACK;
                x->parent->color = RED;
                left_rotate(t, x->parent);
                sibling = x->parent->right;
            }
            if (sibling->left->color == BLACK && sibling->right->color == BLACK) {
                /* case 2: both nephews black -> recolor and move up */
                sibling->color = RED;
                x = x->parent;
            } else {
                if (sibling->right->color == BLACK) {
                    /* case 3: near nephew red -> rotate to a case-4 shape */
                    sibling->left->color = BLACK;
                    sibling->color = RED;
                    right_rotate(t, sibling);
                    sibling = x->parent->right;
                }
                /* case 4: far nephew red -> recolor and rotate, done */
                sibling->color = x->parent->color;
                x->parent->color = BLACK;
                sibling->right->color = BLACK;
                left_rotate(t, x->parent);
                x = t->root;
            }
        } else {
            /* mirror image: x is a right child */
            rb_node_t *sibling = x->parent->left;
            if (sibling->color == RED) {
                sibling->color = BLACK;
                x->parent->color = RED;
                right_rotate(t, x->parent);
                sibling = x->parent->left;
            }
            if (sibling->right->color == BLACK && sibling->left->color == BLACK) {
                sibling->color = RED;
                x = x->parent;
            } else {
                if (sibling->left->color == BLACK) {
                    sibling->right->color = BLACK;
                    sibling->color = RED;
                    left_rotate(t, sibling);
                    sibling = x->parent->left;
                }
                sibling->color = x->parent->color;
                x->parent->color = BLACK;
                sibling->left->color = BLACK;
                right_rotate(t, x->parent);
                x = t->root;
            }
        }
    }
    x->color = BLACK; /* safe no-op when x == t->nil: nil->color is always BLACK */
}

/* Removes key; frees the key copy and (if owned) the value. Returns 0, or -1
 * if key is absent (tree unchanged). */
int rb_delete(rbtree_t *t, const char *key) {
    if (t == NULL || key == NULL) {
        return -1;
    }

    /* phase 1: BST search for z, mirroring rb_find's descent.
     * invariant: key, if present, lies in the subtree rooted at z */
    rb_node_t *z = t->root;
    while (z != t->nil) {
        int c = strcmp(key, z->key);
        if (c == 0) {
            break;
        }
        z = (c < 0) ? z->left : z->right;
    }
    if (z == t->nil) {
        return -1; /* absent: tree, size, and validity all unchanged */
    }

    /* phase 2: CLRS splice. y is the node actually removed from its spot
     * (equal to z unless z has two children); x is the node that lands in
     * y's old position, possibly t->nil. */
    rb_node_t *y = z;
    rb_color_t y_original_color = y->color;
    rb_node_t *x;

    if (z->left == t->nil) {
        x = z->right;
        rb_transplant(t, z, z->right);
    } else if (z->right == t->nil) {
        x = z->left;
        rb_transplant(t, z, z->left);
    } else {
        y = rb_minimum(t, z->right);
        y_original_color = y->color;
        x = y->right;
        if (y->parent == z) {
            x->parent = y; /* needed even if x == t->nil */
        } else {
            rb_transplant(t, y, y->right);
            y->right = z->right;
            y->right->parent = y;
        }
        rb_transplant(t, z, y);
        y->left = z->left;
        y->left->parent = y;
        y->color = z->color;
    }

    /* phase 3: release z's payload. Nothing in the tree references z anymore
     * -- everything that pointed at z now points at y or at whatever
     * replaced it. The value != NULL guard mirrors rb_insert's overwrite
     * path: avoid handing a NULL to a possibly non-NULL-safe value_free. */
    rb_free(z->key);
    if (t->value_free != NULL && z->value != NULL) {
        t->value_free(z->value);
    }
    node_free(t, z);
    t->size--;

    /* phase 4: restore invariants only if a black node was physically
     * removed -- splicing out a red node changes no black-height and cannot
     * create a red-red violation. */
    if (y_original_color == BLACK) {
        rb_delete_fixup(t, x);
    }

    /* phase 5: sentinel hygiene. Unlike CLRS's implicit T.nil, this tree's
     * nil is one object shared for the tree's whole lifetime, so restore its
     * self-referential shape (rb_create's invariant) rather than leaving a
     * stale parent pointer from this call. */
    t->nil->parent = t->nil;

    return 0;
}#ifndef POOL_H
#define POOL_H
#include <stddef.h>
typedef struct rb_pool rb_pool_t;
/* slabs are 4096 bytes */
rb_pool_t *pool_create(size_t obj_size);
/* O(1), from a free list */
void *pool_alloc(rb_pool_t *p);
/* O(1), returns to the free list */
void pool_free(rb_pool_t *p, void *obj);
void pool_stats(const rb_pool_t *p,
size_t *slabs, size_t *live, size_t *free_objs);
/* releases all slabs */
void pool_destroy(rb_pool_t *p);
#endif
#include <stdalign.h>
#include <stddef.h>
#include "pool.h"
#include "fault_alloc.h"

#define SLAB_BYTES 4096

/* A freed object's first bytes hold the link to the next free object. */
typedef struct free_obj {
    struct free_obj *next;
} free_obj_t;

/* Header at the start of every slab. The union pads it to max_align_t so the
 * first object carved after it is suitably aligned for any type. */
typedef union slab {
    union slab *next; /* singly linked list of all slabs, newest first */
    max_align_t align;
} slab_t;

struct rb_pool {
    size_t obj_size;     /* requested size rounded up for alignment and link */
    size_t per_slab;     /* objects carved from one slab */
    slab_t *slabs;       /* every slab owned by the pool, newest first */
    free_obj_t *free;    /* objects returned by pool_free, LIFO */
    char *bump;          /* next never-used object in the newest slab */
    char *bump_end;      /* end of the newest slab's object area */
    size_t nslabs;       /* length of the slabs list */
    size_t live;         /* objects handed out and not yet freed */
};

/* Returns NULL if obj_size is 0, too big to fit one object in a slab, or on
 * allocation failure. Slabs are allocated lazily by pool_alloc. */
rb_pool_t *pool_create(size_t obj_size) {
    const size_t align = alignof(max_align_t);
    const size_t room = SLAB_BYTES - sizeof(slab_t);
    if (obj_size == 0 || obj_size > room) {
        return NULL;
    }
    if (obj_size < sizeof(free_obj_t)) {
        obj_size = sizeof(free_obj_t);
    }
    obj_size = (obj_size + align - 1) / align * align;
    if (obj_size > room) {
        return NULL;
    }

    rb_pool_t *p = rb_malloc(sizeof *p);
    if (p == NULL) {
        return NULL;
    }
    p->obj_size = obj_size;
    p->per_slab = room / obj_size;
    p->slabs = NULL;
    p->free = NULL;
    p->bump = NULL;
    p->bump_end = NULL;
    p->nslabs = 0;
    p->live = 0;
    return p;
}

/* Free list first, then the newest slab's untouched tail, then a new slab.
 * O(1) apart from rb_malloc. NULL on allocation failure, pool unchanged. */
void *pool_alloc(rb_pool_t *p) {
    if (p == NULL) {
        return NULL;
    }
    if (p->free != NULL) {
        free_obj_t *o = p->free;
        p->free = o->next;
        p->live++;
        return o;
    }
    if (p->bump == p->bump_end) {
        slab_t *s = rb_malloc(SLAB_BYTES);
        if (s == NULL) {
            return NULL;
        }
        s->next = p->slabs;
        p->slabs = s;
        p->nslabs++;
        p->bump = (char *)(s + 1);
        p->bump_end = p->bump + p->per_slab * p->obj_size;
    }
    void *o = p->bump;
    p->bump += p->obj_size;
    p->live++;
    return o;
}

/* obj must have come from pool_alloc(p) and not already be freed. NULL-safe. */
void pool_free(rb_pool_t *p, void *obj) {
    if (p == NULL || obj == NULL) {
        return;
    }
    free_obj_t *o = obj;
    o->next = p->free;
    p->free = o;
    p->live--;
}

/* Any out-pointer may be NULL. free_objs counts both freed objects and the
 * never-used tail of the newest slab. */
void pool_stats(const rb_pool_t *p,
                size_t *slabs, size_t *live, size_t *free_objs) {
    size_t ns = (p == NULL) ? 0 : p->nslabs;
    size_t nl = (p == NULL) ? 0 : p->live;
    size_t cap = (p == NULL) ? 0 : ns * p->per_slab;
    if (slabs != NULL) {
        *slabs = ns;
    }
    if (live != NULL) {
        *live = nl;
    }
    if (free_objs != NULL) {
        *free_objs = cap - nl;
    }
}

/* Releases every slab and the pool itself; outstanding objects die with it.
 * NULL-safe. */
void pool_destroy(rb_pool_t *p) {
    if (p == NULL) {
        return;
    }
    slab_t *s = p->slabs;
    /* invariant: s heads the list of slabs not yet freed */
    while (s != NULL) {
        slab_t *next = s->next;
        rb_free(s);
        s = next;
    }
    rb_free(p);
}
