    foreach_ctx_t fc2 = {0};
    fc2.ordered = 1;
    rb_foreach(t, foreach_visit, &fc2);
    CHECK(fc2.ordered == 1);
    CHECK((size_t)fc2.count == rb_size(t));
    CHECK(fc2.sum == 5050); /* sum of 1..100 */

