/* Stack-watermark probe. A balanced 10^6-node tree is only ~20-40 levels
 * deep, so recursion cannot overflow a 64 KB stack; instead we measure how
 * much stack rb_foreach / rb_destroy actually touch. The worker runs on a
 * caller-owned stack pre-painted with WM_BYTE; after join, the lowest
 * repainted byte gives the high-water mark. O(1) auxiliary space means the
 * mark must not grow between a height-2 tree and a height->=20 tree. */
#define WM_STACK (64 * 1024)
#define WM_BYTE 0xCD
#define WM_SLACK 128 /* libc free() path variance; 18+ recursive frames exceed it */

typedef struct {
    rbtree_t *t;
    int destroy; /* 0: rb_foreach(t), 1: rb_destroy(t) */
} wm_job_t;

static void wm_count(const char *key, void *value, void *ctx) {
    (void)key;
    (void)value;
    (*(long *)ctx)++;
}

static void *wm_worker(void *arg) {
    wm_job_t *job = arg;
    if (job->destroy) {
        rb_destroy(job->t);
    } else {
        long n = 0;
        rb_foreach(job->t, wm_count, &n);
        CHECK((size_t)n == rb_size(job->t));
    }
    return NULL;
}

/* Bytes of stk[0..n) overwritten since painting, counted from the top (the
 * stack grows down). Plain volatile loop, not memcmp, and unsanitized: under
 * ASan the dead thread's frames may leave poisoned shadow behind. */
[[gnu::no_sanitize_address]]
static size_t wm_touched(const volatile unsigned char *stk, size_t n) {
    size_t i = 0;
    /* invariant: stk[0..i) all still hold WM_BYTE */
    while (i < n && stk[i] == WM_BYTE) {
        i++;
    }
    return n - i;
}

/* Runs job on a fresh painted WM_STACK-byte stack; returns its high-water
 * mark in bytes, or 0 (with a CHECK failure) if the thread could not run. */
static size_t wm_measure(wm_job_t *job) {
    unsigned char *stk = aligned_alloc(4096, WM_STACK);
    CHECK(stk != NULL);
    if (stk == NULL) {
        return 0;
    }
    memset(stk, WM_BYTE, WM_STACK);
    pthread_attr_t attr;
    pthread_t th;
    size_t used = 0;
    CHECK(pthread_attr_init(&attr) == 0);
    CHECK(pthread_attr_setstack(&attr, stk, WM_STACK) == 0);
    int rc = pthread_create(&th, &attr, wm_worker, job);
    CHECK(rc == 0);
